        return entries.map { it.setScale(2, RoundingMode.UNNECESSARY) }
    }

    private fun validateAmount(amount: BigDecimal) {
        if (amount.signum() < 0) {
            throw IllegalArgumentException("Amount must be non-negative")
        }
