class LruCache<K, V>(val capacity: Int, private val onEvict: (K, V) -> Unit = { _, _ -> }) {
    init {
        require(capacity >= 1) { "capacity must be >= 1" }
    }

    private val map = LinkedHashMap<K, V>()
    private var lastKey: K? = null

    operator fun get(key: K): V? {
        val value = map[key] ?: return null
        if (key != lastKey) {
            // Remove and re-insert to mark as most recently used
            @Suppress("UNCHECKED_CAST")
            val v = map.remove(key) as V?
            map[key] = v
            lastKey = key
        }
        return value
    }

    operator fun set(key: K, value: V) {
        if (map.containsKey(key)) {
            // Update existing entry and mark as most recently used
            @Suppress("UNCHECKED_CAST")
            val v = map.remove(key) as V?
            map[key] = value
            lastKey = key
        } else {
            // Insert new entry
            if (map.size >= capacity) {
                // Evict the least recently used entry (the first one in the map)
                @Suppress("UNCHECKED_CAST")
                val lruEntry = map.entries.first() as Map.Entry<K, V>
                val evictedKey = lruEntry.key
                val evictedValue = lruEntry.value
                map.remove(evictedKey)
                onEvict(evictedKey, evictedValue)
            }
            map[key] = value
            lastKey = key
        }
    }

    fun remove(key: K): V? {
        val value = map.remove(key) ?: return null
        if (lastKey == key) {
            // If we removed the most recently used, find the new most recently used
            if (map.isEmpty()) {
                lastKey = null
            } else {
                // The most recently used is now the second-to-last in insertion order
                // We need to find it. Since LinkedHashMap preserves insertion order,
                // we can iterate to find the last key before the removed one.
                var current: K? = null
                for (k in map.keys) {
                    current = k
                }
                lastKey = current
            }
        }
        return value
    }

    val size: Int get() = map.size

    fun keys(): List<K> {
        return map.keys.toList()
    }

    operator fun contains(key: K): Boolean {
        return map.containsKey(key)
    }
}
