private fun writeValue(sb: StringBuilder, value: Any?, indent: Int, level: Int) {
    when (value) {
        null -> sb.append("null")
        is Boolean -> sb.append(value.toString())
        is String -> writeString(sb, value)
        is Int -> sb.append(value.toString())
        is Long -> sb.append(value.toString())
        is Float -> {
            val d = value.toDouble()
            if (!d.isFinite()) throw IllegalArgumentException("Non-finite float: $value")
            sb.append(d.toString())
        }
        is Double -> {
            if (!value.isFinite()) throw IllegalArgumentException("Non-finite double: $value")
            sb.append(value.toString())
        }
        is Map<*, *> -> writeMap(sb, value, indent, level)
        is List<*> -> writeList(sb, value, indent, level)
        is Array<*> -> writeArray(sb, value, indent, level)
        is Enum<*> -> writeString(sb, value.name)
        else -> throw IllegalArgumentException("Unsupported type: ${value::class}")
    }
}

private fun writeString(sb: StringBuilder, s: String) {
    sb.append('"')
    for (c in s) {
        when {
            c == '"' -> sb.append("\\\"")
            c == '\\' -> sb.append("\\\\")
            c == '\b' -> sb.append("\\b")
            c == '\f' -> sb.append("\\f")
            c == '\n' -> sb.append("\\n")
            c == '\r' -> sb.append("\\r")
            c == '\t' -> sb.append("\\t")
            c < 0x20 -> {
                sb.append(String.format("\\u%04x", c.code))
            }
            else -> sb.append(c)
        }
    }
    sb.append('"')
}

private fun writeMap(sb: StringBuilder, map: Map<*, *>, indent: Int, level: Int) {
    if (map.isEmpty()) {
        sb.append("{}")
        return
    }

    if (indent == 0) {
        sb.append('{')
        var first = true
        for ((k, v) in map) {
            if (!first) sb.append(',')
            first = false
            val keyStr = k as? String ?: throw IllegalArgumentException("Non-String map key: $k")
            writeString(sb, keyStr)
            sb.append(':')
            writeValue(sb, v, indent, level + 1)
        }
        sb.append('}')
    } else {
        val childIndent = " ".repeat(indent * (level + 1))
        val parentIndent = " ".repeat(indent * level)
        sb.append("{\n")
        var first = true
        for ((k, v) in map) {
            if (!first) sb.append(",\n")
            first = false
            val keyStr = k as? String ?: throw IllegalArgumentException("Non-String map key: $k")
            sb.append(childIndent)
            writeString(sb, keyStr)
            sb.append(": ")
            writeValue(sb, v, indent, level + 1)
        }
        sb.append("\n$parentIndent}")
    }
}

private fun writeList(sb: StringBuilder, list: List<*>, indent: Int, level: Int) {
    if (list.isEmpty()) {
        sb.append("[]")
        return
    }

    if (indent == 0) {
        sb.append('[')
