sealed class Token {
    abstract val pos: Int
    data class Ident(val name: String, override val pos: Int) : Token()
    data class Str(val value: String, override val pos: Int) : Token()
    data class Num(val value: Double, override val pos: Int) : Token()
    data class Op(val symbol: String, override val pos: Int) : Token()
    data class Paren(val open: Boolean, override val pos: Int) : Token()
}

class TokenizeException(message: String, val pos: Int) : Exception(message)

fun tokenize(input: String): List<Token> {
    val tokens = mutableListOf<Token>()
    var i = 0
    val n = input.length

    while (i < n) {
        val c = input[i]

        // Skip whitespace
        if (c == ' ' || c == '\t' || c == '\n') {
            i++
            continue
        }

        // Parentheses
        if (c == '(') {
            tokens.add(Token.Paren(true, i))
            i++
            continue
        }
        if (c == ')') {
            tokens.add(Token.Paren(false, i))
            i++
            continue
        }

        // Identifiers
        if (c.isLetter() || c == '_') {
            val start = i
            while (i < n && (input[i].isLetterOrDigit() || input[i] == '_' || input[i] == '.')) {
                i++
            }
            tokens.add(Token.Ident(input.substring(start, i), start))
            continue
        }

        // Numbers or minus sign
        if (c == '-' || c.isDigit()) {
            val isMinus = c == '-'
            val start = i
            var j = i
            if (isMinus) {
                j++
                if (j >= n || !input[j].isDigit()) {
                    throw TokenizeException("Invalid number", start)
                }
            }
            // Parse digits
            while (j < n && input[j].isDigit()) {
                j++
            }
            // Check for fraction part
            if (j < n && input[j] == '.') {
                // .5 is not allowed as a number start, but we're here because we already have digits
                // Actually, if we started with a digit, then 2.5 is valid
                // But 5. would be an error
                j++
                if (j >= n || !input[j].isDigit()) {
                    throw TokenizeException("Malformed number", start)
                }
                while (j < n && input[j].isDigit()) {
                    j++
                }
            }
            val numStr = input.substring(start, j)
            tokens.add(Token.Num(numStr.toDouble(), start))
            i = j
            continue
        }

        // Strings
        if (c == '"' || c == '\'') {
            val quote = c
            val start = i
            i++
            val sb = StringBuilder()
            var terminated = false
            while (i < n) {
                val ch = input[i]
                if (ch == '\\') {
                    i++
                    if (i >= n) {
                        break // Unterminated
                    }
                    val esc = input[i]
                    when (esc) {
                        'n' -> sb.append('\n')
                        else -> sb.append(esc)
                    }
                    i++
                } else if (ch == quote) {
                    terminated = true
                    i++
                    break
                } else {
                    sb.append(ch)
                    i++
                }
            }
            if (!terminated) {
                throw TokenizeException("Unterminated string", start)
            }
            tokens.add(Token.Str(sb.toString(), start))
            continue
        }

        // Operators (longest match first)
        val twoCharOps = listOf("==", "!=", "<=", ">=", "&&", "||")
        var matched = false
        for (op in twoCharOps) {
            if (i + 1 < n && input.substring(i, i + 2) == op) {
                tokens.add(Token.Op(op, i))
                i += 2
                matched = true
                break
            }
        }
        if (matched) continue

        val oneCharOps = listOf("<", ">", "!")
        for (op in oneCharOps) {
            if (c == op[0]) {
                tokens.add(Token.Op(op, i))
                i++
                matched = true
                break
            }
        }
        if (matched) continue

        // If we get here, it's an invalid character
        throw TokenizeException("Unexpected character '$c'", i)
    }

    return tokens
}
