        // Numbers or minus sign
        if (c == '-' || c.isDigit()) {
            val isMinus = c == '-'
            val start = i
            var j = i
            if (isMinus) {
                if (!canHaveMinus()) {
                    throw TokenizeException("Invalid minus sign", start)
                }
                j++
                if (j >= n || !input[j].isDigit()) {
                    throw TokenizeException("Invalid number", start)
                }
            }
            // Parse digits
            while (j < n && input[j].isDigit()) {
                j++
            }
            // Check for fraction part
            if (j < n && input[j] == '.') {
                j++
                if (j >= n || !input[j].isDigit()) {
                    throw TokenizeException("Malformed number", start)
                }
                while (j < n && input[j].isDigit()) {
                    j++
                }
            }
            val numStr = input.substring(start, j)
            tokens.add(Token.Num(numStr.toDouble(), start))
            i = j
            continue
        }

        // Strings
        if (c == '"' || c == '\'') {
            val quote = c
            val start = i
            i++
            val sb = StringBuilder()
            var terminated = false
            while (i < n) {
                val ch = input[i]
                if (ch == '\\') {
                    i++
                    if (i >= n) {
                        break // Unterminated
                    }
                    val esc = input[i]
                    when (esc) {
                        'n' -> sb.append('\n')
                        else -> sb.append(esc)
                    }
                    i++
                } else if (ch == quote) {
                    terminated = true
                    i++
                    break
                } else {
                    sb.append(ch)
                    i++
                }
            }
            if (!terminated) {
                throw TokenizeException("Unterminated string", start)
            }
            tokens.add(Token.Str(sb.toString(), start))
            continue
        }

        // Operators (longest match first)
        val twoCharOps = listOf("==", "!=", "<=", ">=", "&&", "||")
        var matched = false
        for (op in twoCharOps) {
            if (i + 1 < n && input.substring(i, i + 2) == op) {
                tokens.add(Token.Op(op, i))
                i += 2
                matched = true
                break
            }
        }
        if (matched) continue

        val oneCharOps = listOf("<", ">", "!")
        for (op in oneCharOps) {
            if (c == op[0]) {
                tokens.add(Token.Op(op, i))
                i++
                matched = true
                break
            }
        }
        if (matched) continue

        // If we get here, it's an invalid character
        throw TokenizeException("Unexpected character '$c'", i)
    }

    return tokens
}
