def merge(base: dict, *overrides: dict) -> dict:
    """Deep merge configuration layers where later overrides win.

    Rules:
    - Dicts are merged recursively.
    - Non-dict values in override replace base value (lists replaced, not concatenated).
    - A key whose override value is None deletes that key from the result.
    - A key ending in '+' appends items to the base list with the same name minus '+'.
      If base value exists and is not a list, raise TypeError.
      The '+' key itself never appears in the result.
    - Inputs are not mutated; result is a deep copy (no shared mutable dicts/lists).
    """
    import copy

    def _deep_copy(value):
        """Deep copy a value."""
        if isinstance(value, dict):
            return {k: _deep_copy(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_deep_copy(item) for item in value]
        else:
            # Immutable types can be returned as-is
            return value

    def _merge_two(base_dict: dict, override_dict: dict) -> dict:
        """Merge two dicts deeply, returning a new dict."""
        result = {}

        # Start with a deep copy of base
        for key, val in base_dict.items():
            if isinstance(val, dict):
                result[key] = _deep_copy(val)
            elif isinstance(val, list):
                result[key] = _deep_copy(val)
            else:
                result[key] = val

        # Apply override
        for key, val in override_dict.items():
            if val is None:
                # Delete key from result
                result.pop(key, None)
            elif key.endswith('+'):
                # Append mode
                base_key = key[:-1]
                items_to_append = _deep_copy(val)
                if not isinstance(items_to_append, list):
                    # The override value for a '+' key should be a list
                    # But let's handle it gracefully - treat as single item? 
                    # Actually, the spec says "appends the items to the base list"
                    # so we expect a list. If it's not a list, we might want to raise or wrap.
                    # Let's just wrap it in a list for safety, but actually the spec implies it's a list.
                    # I'll treat non-list as an error or wrap. Let's wrap for robustness.
                    items_to_append = [items_to_append]

                if base_key in result:
                    existing = result[base_key]
                    if not isinstance(existing, list):
                        raise TypeError(
                            f"Cannot append to non-list value for key '{base_key}'"
                        )
                    # Append items to the existing list (which is already a deep copy)
                    existing.extend(items_to_append)
                else:
                    # Base doesn't have this key, create new list
                    result[base_key] = items_to_append
            elif isinstance(val, dict):
                if key in result and isinstance(result[key], dict):
                    # Recursive merge
                    result[key] = _merge_two(result[key], val)
                else:
                    # Override with deep copy of the dict
                    result[key] = _deep_copy(val)
            else:
                # Non-dict, non-None value: replace
                result[key] = _deep_copy(val)

        return result

    # Start with an empty dict and merge base first, then each override in order
    result = {}

    # Merge base into result
    for key, val in base.items():
        if isinstance(val, dict):
            result[key] = _deep_copy(val)
        elif isinstance(val, list):
            result[key] = _deep_copy(val)
        else:
            result[key] = val

    # Merge each override in order
    for override in overrides:
        result = _merge_two(result, override)

    return result
