def parse_duration(s: str) -> int:
    """Parse a human-readable duration string into seconds."""
    if not isinstance(s, str):
        raise ValueError("Input must be a string")

    # Do NOT strip leading/trailing whitespace — the spec says single spaces between parts only.
    # Leading or trailing spaces are invalid characters.

    if not s:
        raise ValueError("Empty input")

    units = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    unit_order = ['d', 'h', 'm', 's']

    import re

    # Find all matches of <integer><unit>
    pattern = r'(\d+)([a-zA-Z])'
    matches = list(re.finditer(pattern, s))

    if not matches:
        raise ValueError("No valid duration parts found")

    # Check that the entire string is composed of these parts with optional single spaces between them
    prev_end = 0
    for i, match in enumerate(matches):
        start, end = match.start(), match.end()
        if i == 0:
            if start != 0:
                raise ValueError("Invalid characters at start")
        else:
            gap = s[prev_end:start]
            if gap != '' and gap != ' ':
                raise ValueError(f"Invalid separator: {gap!r}")
        prev_end = end

    # Check that we consumed the entire string
    if prev_end != len(s):
        raise ValueError("Trailing invalid characters")

    # Now validate the units and order
    total_seconds = 0
    last_unit_index = -1

    for match in matches:
        num_str = match.group(1)
        unit_char = match.group(2).lower()

        if unit_char not in units:
            raise ValueError(f"Unknown unit: {unit_char}")

        current_unit_index = unit_order.index(unit_char)

        # Check order: each unit must come after the previous one (strictly increasing index)
        if current_unit_index <= last_unit_index:
            raise ValueError("Units out of order or repeated")

        last_unit_index = current_unit_index

        total_seconds += int(num_str) * units[unit_char]

    return total_seconds


def format_duration(seconds: int) -> str:
    """Format seconds into a canonical human-readable duration string."""
    if not isinstance(seconds, int):
        raise ValueError("Input must be an integer")
    if seconds < 0:
        raise ValueError("Negative input")

    if seconds == 0:
        return "0s"

    days = seconds // 86400
    remainder = seconds % 86400
    hours = remainder // 3600
    remainder %= 3600
    minutes = remainder // 60
    secs = remainder % 60

    parts = []
    if days > 0:
        parts.append(f"{days}d")
