    if total_items == 0:
        total_pages = 1
    else:
        total_pages = (total_items + per_page - 1) // per_page

    start = (page - 1) * per_page
    end = start + per_page
    items_slice = items[start:end]

    return {
        "items": items_slice,
        "page": page,
        "total_pages": total_pages,
        "has_next": page < total_pages,
        "has_prev": page > 1,
    }
