def flatten(obj, sep=".") -> dict:
    if not isinstance(obj, dict):
        raise TypeError("top-level object must be a dict")

    result = {}

    def _flatten(key_prefix, value):
        if isinstance(value, dict):
            if len(value) == 0:
                # empty dict is a leaf
                if key_prefix:
                    result[key_prefix] = value
                else:
                    # This shouldn't happen since top-level is handled separately
                    pass
                return
            for k, v in value.items():
                if not isinstance(k, str):
                    raise ValueError("keys must be strings")
                if sep in k:
                    raise ValueError(f"key {k!r} contains separator {sep!r}")
                new_key = f"{key_prefix}{sep}{k}" if key_prefix else k
                _flatten(new_key, v)
        elif isinstance(value, list):
            if len(value) == 0:
                # empty list is a leaf
                if key_prefix:
                    result[key_prefix] = value
                return
            for i, item in enumerate(value):
                new_key = f"{key_prefix}{sep}{i}" if key_prefix else str(i)
                _flatten(new_key, item)
        else:
            # leaf value
            if key_prefix:
                result[key_prefix] = value

    # Handle top-level dict
    for k, v in obj.items():
        if not isinstance(k, str):
            raise ValueError("keys must be strings")
        if sep in k:
            raise ValueError(f"key {k!r} contains separator {sep!r}")
        _flatten(k, v)

    return result


def unflatten(flat: dict, sep="."):
    if not isinstance(flat, dict):
        raise TypeError("input must be a dict")

    # Build the nested structure
    root = {}

    def _is_valid_index(segment):
        """Check if segment is a non-negative integer without leading zeros."""
        if not segment.isdigit():
            return False
        if len(segment) > 1 and segment[0] == '0':
            return False
        return True

    # Process each key-value pair
    for path, value in flat.items():
        segments = path.split(sep)

        # Navigate/create the structure
        current = root

        for i, seg in enumerate(segments):
            is_last = (i == len(segments) - 1)

            if _is_valid_index(seg):
                idx = int(seg)

                if is_last:
                    # Set the value at this index
                    if isinstance(current, list):
                        if idx >= len(current):
                            raise ValueError(f"list index {idx} out of range")
                        current[idx] = value
                    elif isinstance(current, dict):
                        if str(idx) in current:
                            raise ValueError(f"conflict at key {str(idx)}")
                        current[str(idx)] = value
                    else:
                        raise ValueError(f"cannot set index {idx} on non-container")
                else:
                    # Need to navigate deeper
                    if isinstance(current, list):
                        if idx >= len(current):
                            raise ValueError(f"list index {idx} out of range")
                        current = current[idx]
                    elif isinstance(current, dict):
                        key_str = str(idx)
                        if key_str in current:
                            current = current[key_str]
                        else:
                            # Create a placeholder - we'll determine type later
                            current[key_str] = {}
                            current = current[key_str]
                    else:
                        raise ValueError(f"cannot navigate index {idx} on non-container")
            else:
                if is_last:
                    # Set the value at this key
                    if isinstance(current, dict):
                        if seg in current:
                            raise ValueError(f"conflict at key {seg}")
                        current[seg] = value
                    elif isinstance(current, list):
                        raise ValueError(f"cannot set key {seg} on a list")
                    else:
                        raise ValueError(f"cannot set key {seg} on non-container")
                else:
                    # Need to navigate deeper
                    if isinstance(current, dict):
                        if seg in current:
                            current = current[seg]
                        else:
                            current[seg] = {}
                            current = current[seg]
                    elif isinstance(current, list):
                        raise ValueError(f"cannot navigate key {seg} on a list")
                    else:
                        raise ValueError(f"cannot navigate key {seg} on non-container")

    # Now we need to convert dicts that should be lists
    def _convert_to_lists(node):
        if isinstance(node, dict):
            # Check if all keys are valid indices
            if len(node) == 0:
                return node

            keys = list(node.keys())
            all_indices = True
            indices = []
            for k in keys:
                if _is_valid_index(k):
                    indices.append(int(k))
                else:
                    all_indices = False
                    break

            if all_indices and len(indices) == len(keys):
                # Check if indices are exactly 0..n-1
                n = len(indices)
                expected = set(range(n))
                actual = set(indices)
                if actual != expected:
                    raise ValueError(f"list indices must be exactly 0..{n-1}, got {sorted(indices)}")

                # Convert to list
                lst = [None] * n
                for k, v in node.items():
                    idx = int(k)
                    lst[idx] = _convert_to_lists(v)
                return lst
            else:
                # It's a dict, convert children
                for k in keys:
                    node[k] = _convert_to_lists(node[k])
                return node
        elif isinstance(node, list):
            for i in range(len(node)):
                node[i] = _convert_to_lists(node[i])
            return node
        else:
            return node

    result = _convert_to_lists(root)

    # The root should be a dict (since top-level was a dict)
    if not isinstance(result, dict):
        raise ValueError("root must be a dict")

    return result
