import heapq
from collections import defaultdict
import string


def route(grid: list[str]) -> tuple[int, str] | None:
    # Validate grid
    if not grid:
        raise ValueError("Empty grid")

    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    for i, row in enumerate(grid):
        if len(row) != cols:
            raise ValueError(f"Ragged rows: row {i} has length {len(row)}, expected {cols}")

    start = None
    end = None
    pads = defaultdict(list)
    valid_chars = set("SE#.") | set(str(d) for d in range(1, 10)) | set(string.ascii_lowercase)

    for r in range(rows):
        for c in range(cols):
            ch = grid[r][c]
            if ch not in valid_chars:
                raise ValueError(f"Unknown character {ch!r} at ({r}, {c})")
            if ch == 'S':
                if start is not None:
                    raise ValueError("More than one S")
                start = (r, c)
            elif ch == 'E':
                if end is not None:
                    raise ValueError("More than one E")
                end = (r, c)
            elif ch in string.ascii_lowercase:
                pads[ch].append((r, c))

    if start is None:
        raise ValueError("No S found")
    if end is None:
        raise ValueError("No E found")

    for letter, positions in pads.items():
        if len(positions) == 1 or len(positions) > 2:
            raise ValueError(f"Letter {letter!r} appears {len(positions)} times, expected 0 or 2")

    # Build pad mapping: position -> other position
    pad_map = {}
    for letter, positions in pads.items():
        if len(positions) == 2:
            p1, p2 = positions[0], positions[1]
            pad_map[p1] = p2
            pad_map[p2] = p1

    def get_cost(r: int, c: int) -> int:
        ch = grid[r][c]
        if ch == 'S' or ch == 'E':
            return 1
        if ch == '.':
            return 1
        if ch in string.digits:
            return int(ch)
        if ch in string.ascii_lowercase:
            return 1
        if ch == '#':
            return -1  # wall, shouldn't be called
        raise ValueError(f"Unexpected char {ch}")

    # Dijkstra from E to compute min cost to reach E for each cell.
    INF = float('inf')
    dist_to_end = [[INF] * cols for _ in range(rows)]
    dist_to_end[end[0]][end[1]] = 0

    # Priority queue: (cost, r, c)
    pq = [(0, end[0], end[1])]

    while pq:
        cost, r, c = heapq.heappop(pq)
        if cost > dist_to_end[r][c]:
            continue

        # Try all moves from (r, c) to neighbors
        # U, D, L, R
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                nch = grid[nr][nc]
                if nch == '#':
                    continue
                move_cost = get_cost(nr, nc)
                new_cost = cost + move_cost
                if new_cost < dist_to_end[nr][nc]:
                    dist_to_end[nr][nc] = new_cost
                    heapq.heappush(pq, (new_cost, nr, nc))

        # Teleport: if standing on a pad, can jump to other pad for cost 2
        if (r, c) in pad_map:
            tr, tc = pad_map[(r, c)]
            new_cost = cost + 2
            if new_cost < dist_to_end[tr][tc]:
                dist_to_end[tr][tc] = new_cost
                heapq.heappush(pq, (new_cost, tr, tc))

    min_total_cost = dist_to_end[start[0]][start[1]]
    if min_total_cost == INF:
