            mc = get_cost(nr, nc)
            if so_far + mc + dist_to_end[nr][nc] == min_total_cost:
                moves.append('D')
                r, c = nr, nc
                so_far += mc
                found = True
                break

        # L
        nr, nc = r, c - 1
        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != '#':
            mc = get_cost(nr, nc)
            if so_far + mc + dist_to_end[nr][nc] == min_total_cost:
                moves.append('L')
                r, c = nr, nc
                so_far += mc
                found = True
                break

        # R
        nr, nc = r, c + 1
        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != '#':
            mc = get_cost(nr, nc)
            if so_far + mc + dist_to_end[nr][nc] == min_total_cost:
                moves.append('R')
                r, c = nr, nc
                so_far += mc
                found = True
                break

