        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease  # list of identifiers or None
        self.build = build  # list of identifiers or None

    def _cmp(self, other):
        if self.major != other.major:
            return -1 if self.major < other.major else 1
        if self.minor != other.minor:
            return -1 if self.minor < other.minor else 1
        if self.patch != other.patch:
            return -1 if self.patch < other.patch else 1

        # Compare prerelease
        if self.prerelease is None and other.prerelease is None:
            return 0
        if self.prerelease is None:
            return 1  # release > prerelease
        if other.prerelease is None:
            return -1  # prerelease < release

        # Compare identifier lists
        for a, b in zip(self.prerelease, other.prerelease):
            cmp_result = _compare_identifier(a, b)
            if cmp_result != 0:
                return cmp_result

        if len(self.prerelease) == len(other.prerelease):
            return 0
        return -1 if len(self.prerelease) < len(other.prerelease) else 1

    def __eq__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp(other) == 0

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp(other) < 0

    def __le__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp(other) <= 0

    def __gt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp(other) > 0

    def __ge__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp(other) >= 0

    def __hash__(self):
        # Build metadata is ignored for equality/ordering
        return hash((self.major, self.minor, self.patch, tuple(self.prerelease) if self.prerelease else None))

