#!/usr/bin/env bash
set -euo pipefail

usage() {
    echo "Usage: $0 [-n N] [-i]" >&2
    exit 2
}

N=10
IGNORE_CASE=0

while getopts ":n:i" opt; do
    case "$opt" in
        n)
            N=$OPTARG
            if ! [[ $N =~ ^[0-9]+$ ]] || [ "$N" -le 0 ]; then
                usage
            fi
            ;;
        i)
            IGNORE_CASE=1
            ;;
        :)
            echo "Option -$OPTARG requires an argument." >&2
            usage
            ;;
        \?)
            echo "Invalid option: -$OPTARG" >&2
            usage
            ;;
    esac
done

# Read all input into a variable
input=$(cat)

if [ -z "$input" ]; then
    exit 0
fi

# Use awk to process the text
LC_ALL=C awk -v ignore_case="$IGNORE_CASE" -v limit="$N" '
BEGIN {
    IGNORE_CASE = (ignore_case == "1") ? 1 : 0
}
{
    line = $0
    # Tokenize: split on any character that is NOT an ASCII letter, digit, or apostrophe
    n = split(line, tokens, /[^A-Za-z0-9\x27]+/)
    for (i = 1; i <= n; i++) {
        word = tokens[i]
        if (IGNORE_CASE) {
            word = tolower(word)
        }
        # Strip leading apostrophes
        while (substr(word, 1, 1) == "\x27") {
            word = substr(word, 2)
        }
        # Strip trailing apostrophes
        while (length(word) > 0 && substr(word, length(word), 1) == "\x27") {
            word = substr(word, 1, length(word) - 1)
        }
        if (word != "") {
            count[word]++
        }
    }
}
END {
    # Collect words and counts into arrays
    nwords = 0
    for (w in count) {
        nwords++
        words[nwords] = w
        cnts[nwords] = count[w]
    }

    # Sort by count descending, then word ascending (byte order)
    # Simple selection sort
    for (i = 1; i <= nwords; i++) {
        best = i
        for (j = i + 1; j <= nwords; j++) {
            if (cnts[j] > cnts[best] || (cnts[j] == cnts[best] && words[j] < words[best])) {
                best = j
            }
        }
        # Swap i and best
        tmpw = words[i]; words[i] = words[best]; words[best] = tmpw
        tmpc = cnts[i]; cnts[i] = cnts[best]; cnts[best] = tmpc
    }

    out = (nwords < limit) ? nwords : limit
    for (i = 1; i <= out; i++) {
        print cnts[i], words[i]
    }
}
' <<< "$input"
